const body = $json.body ?? $json;
const data = body.data ?? body; const key = data.key ?? {};
if (key.fromMe === true) return [{json:{ignored:true,reason:'from_me'}}];
const remoteJid = key.remoteJid ?? data.remoteJid ?? null; const m=data.message ?? {};
const text=m.conversation ?? m.extendedTextMessage?.text ?? m.imageMessage?.caption ?? m.videoMessage?.caption ?? data.text ?? null;
if (!remoteJid || !text || !String(text).trim()) return [{json:{ignored:true,reason:'unsupported_or_empty_message',remoteJid}}];
return [{json:{ignored:false,correlation_id:`${Date.now()}-${Math.random().toString(36).slice(2,10)}`,remoteJid,pushName:data.pushName??null,message_id:key.id??null,text:String(text).trim().slice(0,4000),received_at:new Date().toISOString()}}];

